const factRow = rows => rows.length ? `<div class="facts">${rows.map(([name, textValue]) => `<span>${icon(name)}${esc(textValue)}</span>`).join('')}</div>` : '';
const facts = (p, max = 3) => { if (isLand(p)) return factRow([p.land_area ? ['layers', landSize(p.land_area)] : null, p.zoning ? ['building', p.zoning] : null, ['check', saleMethodLabel(p)]].filter(Boolean).slice(0, max)); if ((p.sector || 'residential') === 'commercial') return areaFacts(p, max); if (p.property_type === 'land') { const pairs = (p.details || []).filter(d => Array.isArray(d) && d.length === 2); const short = pairs.filter(([l, v]) => (l + v).length <= 36); return factRow((short.length >= Math.min(max, pairs.length) ? short : pairs).slice(0, max).map(([l, v]) => ['check', `${l}: ${v}`])); } return factRow([['bed', p.bedrooms === 0 ? 'Studio' : `${p.bedrooms} beds`], ['bath', `${p.bathrooms} bath${p.bathrooms === 1 ? '' : 's'}`], ['car', `${p.parking} car${p.parking === 1 ? '' : 's'}`]].slice(0, max)); };
const img = (p, cls = '', eager = false) => `<img class="${cls}" src="${esc(p.media?.[0]?.url || '/assets/courtyard.webp')}" alt="${esc(p.media?.[0]?.alt || (p.is_demo===false ? p.title : `${p.title}, fictional concept home`))}" ${eager?'fetchpriority="high"':'loading="lazy"'} width="1024" height="688">`;
