async function api(path, options = {}) { const res = await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...options.headers},body:options.body === undefined ? undefined : JSON.stringify(options.body)});const data = await res.json();if(!res.ok)throw Object.assign(new Error(data.error || 'Please try again.'),{status:res.status});return data; }
