 const plurals={development_site:'Development sites',commercial_industrial:'Commercial and industrial land',rural:'Rural land',subdivision_investment:'Subdivision and investment land'};
 const type=q.get('type');const label=sector==='commercial'?commercialTypes.find(([v])=>v===type)?.[1]:plurals[type];
 if(label)parts[0]=label;
