function documentSection(p) { const supplied=(p.documents||[]).filter(d=>Array.isArray(d)&&d[0]&&d[1]); const commercial=(p.sector||'residential')==='commercial'; const expected=commercial?['Floor plan','Information memorandum']:isLand(p)?['Site plan','Information memorandum']:['Floor plan']; const labels=[...expected,...supplied.map(([label])=>label).filter(label=>!expected.some(e=>e.toLowerCase()===label.toLowerCase()))]; const open=p.transaction_status==='available'&&p.publication_state==='published';
 const rows=labels.map(label=>{const match=supplied.find(([l])=>l.toLowerCase()===label.toLowerCase()); if(match)return `<li class="document-row"><span>${esc(label)}</span><a class="link" href="${esc(match[1])}" target="_blank" rel="noopener">Open ${icon('arrow')}</a></li>`; return `<li class="document-row is-awaiting"><span>${esc(label)}</span>${open?`<button type="button" class="link" data-action="enquire" data-topic="Please send the ${esc(label.toLowerCase())} for ${esc(p.title)}.">Request it ${icon('arrow')}</button>`:'<span class="small muted">Not yet supplied</span>'}</li>`;});
 return `<h2>Documents</h2><ul class="document-list">${rows.join('')}</ul><p class="small muted">Documents are released by the team once the property supplies them.</p>`; }
