 const gallery=many?`<span class="card-gallery">${media.map((m,i)=>`<img class="${i?'':'is-active'}" src="${esc(m.url)}" alt="${esc(m.alt)}" ${i?'loading="lazy"':''} width="1024" height="688">`).join('')}</span>`:img(p);
