function locationSection(p,real) {const hasLoc=!!p.has_location;const lat=Number(p.latitude),lng=Number(p.longitude);const addressLine=p.address?esc(p.address):`${esc(p.locality)}. ${real?'Only the locality is shown. Ask the team for the exact address.':'This is a fictional location used for the concept; no map is available.'}`;const coords=`${lat.toFixed(5)}, ${lng.toFixed(5)}`;const mapBlock=hasLoc?`<div class="location-map" id="location-map"><div class="map-placeholder">${icon('pin')}<span>${esc(p.locality)}</span><button type="button" class="btn secondary" data-action="show-map">Show map</button><p class="small muted">Loads Google Maps</p></div></div><div class="location-links"><a class="link" href="https://www.google.com/maps/search/?api=1&query=${lat},${lng}" target="_blank" rel="noopener">Open in Google Maps ${icon('arrow')}</a><a class="link" href="https://www.google.com/maps/dir/?api=1&destination=${lat},${lng}" target="_blank" rel="noopener">Get directions ${icon('arrow')}</a><a class="link" href="https://maps.apple.com/?ll=${lat},${lng}&q=${encodeURIComponent(p.title)}" target="_blank" rel="noopener">Apple Maps ${icon('arrow')}</a></div><p class="coords small muted">${esc(coords)} <button type="button" class="link" data-action="copy-coords" data-coords="${esc(coords)}">Copy</button></p>`:'';const directionsBlock=p.directions?`<h2>Getting there</h2>${String(p.directions).split(/\n\s*\n/).filter(Boolean).map(para=>`<p>${esc(para)}</p>`).join('')}`:'';return `<div id="location"><h2>Location</h2><p>${addressLine}</p>${mapBlock}${directionsBlock}</div>`;}
// The editorial format (docs/31) is a long read about one listing: a full-height opener, the
// property's own argument, its facts and its photographs, then the rest of the catalogue. It is a
// feature page hung off a listing, not a second homepage, so it lives at /feature/<slug> and is
// linked from the homepage and from the listing itself. /editorial was its trial address and is
// redirected here so the link Clent was given still works.
async function feature(slug) {
  const {properties}=await api('/properties?sector=all');
  const lead=slug?properties.find(o=>o.slug===slug):properties.find(o=>o.featured&&o.is_demo===false);
  // A feature needs the property's own words. Without them the page would be a photo gallery with
  // a headline, so it says so rather than rendering something thin. Nothing links here in that case.
  if(!lead||!lead.why)return `<div class="wrap section">${empty(lead?'There is no feature for this property yet.':'This feature isn\u2019t available.',lead?'The listing itself has the full details.':'The property may have been withdrawn.',lead?`/properties/${lead.slug}`:'/properties?sector=all',lead?'View the listing':'Browse every property')}</div>`;
  if(location.pathname!=='/feature/'+lead.slug)history.replaceState({},'','/feature/'+lead.slug);
  document.title=lead.title+' \u2014 RealDistrict';
  return editorialView({lead,properties,esc,icon,price,typeLabel,card});
}
